窗外的星星继续慢慢地移。他把手杖立在地上，双手叠在杖头。

「年轻人。」

「我这一路上见过很多人。有的人上车的时候很急，下车的时候更急。也有的人，坐了很多站，一直没想好要在哪里下。」

「你不必现在就想好。」

「坐一会儿也行。」

他抬起手杖，指了指窗外某个方向。

「那里，有一颗已经不在的星。」

「名册上还有记录，坐标也还在。可它很多年前就熄了。」

「我们还在按它的位置航行。因为到那里之前，没有别的参照物。」

他把手杖放回地面，轻轻一顿。

「你看，人有时候也需要这样的东西。一个已经不在了、但还能拿来定位的点。」

车厢轻轻晃了一下，窗外的星移了一小段。

「我说这些，不是要你伤感。」他转过脸来，语气很平常，「只是想说明一件事——」

「你现在觉得撑不住的那些东西，将来可能会变成你用来定位自己的东西。」

「不是安慰。是我这几十年的一点经验。」

他终于在旁边的座位坐下，把外套的下摆整理好。

「坐吧。列车还要开很久。」

「你要是累了，就靠着睡。到站我叫你。」
