所以你给人的印象是：明明一直趴着，事情却总是做完了。因为你把力气全花在**找最短路径**上，而不是花在抱怨上。

你不是不努力，你是**拒绝无效努力**。让你加班到半夜做一份没人看的报告，你会当场叹气；让你花十分钟堵住一个会引发三个月麻烦的漏洞，你会立刻动手，一声不吭。

