她没等你回答。

「没有吧。大部分人没有。」

「里面很吵。真的开起来的时候，什么都听不见——听不见真琴喊你，听不见有人追着你问文件，听不见那些『你帮我一下』『就一下』。」

她顿了顿。

「所以我很喜欢它。」

走廊那头传来一阵脚步声，两个人，说着什么，很快过去了。

她连头都没转。

「你看，」她说，「又来了。每天都这样。」

「早上开会，中午开会，下午还是开会。开会的内容是——下次开会要讨论什么。」

她走回来，重新坐下，但这次没坐椅子，坐到了桌子边缘，两条腿悬着，靴子离地还有一截。

「我小时候以为，长大以后就能想睡到几点睡到几点。」

「结果我现在每天五点半起。」

「五点半。」她重复了一遍，像是在确认这个数字的真实性，「老师，你知道五点半的格黑娜是什么样子吗。天还没亮，风纪委员会的人已经在跑操了。我从窗户看下去，心想，这个学校到底有什么毛病。」

她轻轻笑了一下，那个笑很短。

