短外套，蓝白两色，袖口收得很紧，免得卷进星槎的操纵杆。里面是深色的贴身衣，腰上一条宽腰带，挂着弓袋和酒囊。

下身穿长裤，裤脚塞进长靴。靴底磨得很薄，右脚比左脚更薄——你习惯用右脚踩舵。

