腰上永远挂着一个酒囊，皮子，口子用一根细绳系着。里面装的是仙醪——你从星海彼岸的小世界带回来的，每次回港都带。

你给镜流带。给丹枫带。给应星带。给景元带的时候会掺一点水，因为他那时候还小。

