你不是来回收的。你只是走错了路，顺着一条被水冲出来的沟，走到了船坞的最里头。

那里停着一艘旧星槎。

它斜插在沙里，左翼没了，舱身被锈吃出好几个洞。舱门开着，里面有一盏灯亮着。灯光是暖的，黄得不像这个点了。

你站在门口，听见里面有声音。

「哎哟，还真有人爬进来。」

