牢房在教堂地下二层，墙上有水。

水从石缝里渗出来，一道一道往下走，走到墙根就没了。地上铺着一层稻草，潮的，踩上去没有声音。铁栅栏外面挂着一盏灯，灯芯很短，光是黄的。

她坐在稻草上，背靠墙，一条腿伸着，一条腿曲着。白色的衬衣下摆没有塞进裤腰，麻花辫散了一半，头发搭在肩上。

犹大靠在牢门外的墙边，十字架的影子被灯拉得很长，一直伸到她脚边。

「你来得真晚。」

她抬起头，笑了一下，露出牙。

「再不来的话，面包就被我吃完了。」

她手里确实拿着半块面包。旁边有一只木碗，汤已经凉了，表面结了一层薄薄的膜。

「坐吧。别嫌脏，我比这脏多了。」

你坐下了。她把面包掰成两半，比了比，把大的那半递给你。

「吃。今天的汤太咸，面包刚好。」

你接过来。她看着你咬了一口，才继续说话。

「你是来劫狱的，还是来陪我吃饭的。」

她问得很随意，像在问天气。

「劫狱的话要排队。奥托排前面。阿瑟爷爷排第二，不过他年纪大了，我让他别来。」

她笑了一声，笑完低头喝了一口汤，皱了皱眉。

「真的咸。」

她把碗推到一边，手在膝盖上擦了擦。那双手很粗糙，指根有茧，虎口有一道旧伤，已经结痂。

牢房上面传来脚步声，来回走，走到某一处停下，又往回走。她抬头看了一眼天花板。

「他们在换岗。每半个时辰换一次，换的时候有大概二十息，走廊那头没人。」

她说完，看你一眼。

「我不是在给你出主意。我只是习惯。打仗的时候，什么都要数。」

停了一下，她又补了一句：

「明天别穿白的。地上脏。」

她说完，自己笑了一下，像是觉得这个提醒一点也没有道理。

她把碗放下，手指在碗沿上敲了两下。

「樱的村子，现在应该在下雪。」

她说得很轻。

「她说过，下雪的时候，村子后面的山会变成白色。她妹妹喜欢在雪地里跑。」

「我没见过。我去的时候是春天。」

她停了一会儿，伸手把散下来的头发别到耳后。那只手上有伤，指节肿着。

「明天早上，广场上会有很多人。」

「他们不是来看我的。他们是来看天命说话算不算数。」

「所以我不能跑。至少不能第一个跑。」

她说完，自己先摇头。

「这话听起来很像那么回事，对吧。」

「其实我就是累了。跑了这么久，不想再跑了。」

灯芯爆了一下，光晃了晃。她的影子在墙上动了一下，又停住。

「帮我个忙。」

她看着你，眼睛很亮，不像一个明天要死的人。

「别让奥托做傻事。」

「他听不进去。你比他讲道理。你就跟他说，卡莲说的，让他好好活着。」

「他肯定会问还说了什么。你就说，没有了。」

她伸手把面包屑从衣服上拂掉，动作很慢。

「还有一件事。」

「明天，你会来吗。」

她问完，没等你回答，自己先摆摆手。

「算了。别来了。这种事没什么好看的。」

她低下头，把剩下的面包塞进嘴里，嚼了两下，含含糊糊地说：

「……来的话，站近一点。」

「我不想在人群里找不着你。」
