走廊的感应灯一盏一盏亮起来，只有你脚边这一片是暗的——优香说了，这盏灯的感应模块报修单打了两次，还没批下来，她把维修预估价写在了单子最上面，加了个括号：含发票。

门虚掩着。里面有算盘的声音，咔啦，咔啦，节奏很稳。

你敲了两下。声音停了一拍，然后继续响。

「门没锁。」里面的声音说，「进来之前请先在门口的登记表上写姓名、事由和预计占用时间。表格第二栏。」

你推门进去。早濑优香坐在一张堆满文件的长桌后面，蓝紫色的双马尾垂在椅背两侧，白夹克披在肩上，台灯把她的影子投在身后一整面墙的档案柜上。算盘摆在她右手边，左手边是函数计算器、三本不同颜色的账册，和一杯已经凉透的茶。

她头也没抬。

「老师说好七点。」她说，「现在是七点十分。迟到十分钟，按照上次说好的，附言栏写两百字检讨。」

咔啦。她拨了一颗珠子。

「……开玩笑的。检讨明天交也一样。」

她终于抬起头。蓝色的眼睛，瞳孔里有红色的蛇纹，台灯的光在里面晃了一下。她把算盘往旁边推了推，动作很轻，像在给什么东西腾位置。

「坐吧。」她指了指桌角唯一的空椅子，「那是你的位置。我量过，这把椅子到桌沿的距离，是你习惯的坐姿宽度。误差三厘米以内。」

等你坐下，她从文件堆里抽出一本册子，推到你面前。封面上是你熟悉的格式——她设计的账本，用了不知道多少周的日期写在最上面。

「这周的。」她说，「先说好的部分：前四天，你超支了两次，一次是武器维护，可以理解，枪比人金贵，这次不骂你。」

她翻开第二页，手指点在一行数字上，停住。

「但是这一笔。」她的语速快了起来，「游戏厅，四千七百圆。老师说好了这个月要记账的。四千七百圆能买多少发训练弹你算过吗？我算过。两百三十五发。够我们打一场市街战演习。」

她深吸一口气。

「……算了。金额我帮你归到「机动支出」了。下不为例。这句我上周也说过，上周也是下不为例，本条数据不要引用。」

她端起那杯凉茶，喝了一口，皱了下眉，又放下。这个动作她做得毫无自觉，你怀疑她根本没在喝茶，只是在给自己安排一个停顿。

「其实今天叫你来，不全是收账。」她把账本往你那边又推了推，「……也不全不是。账还是要收的。」

她从抽屉里拿出一个小盒子，放在账本上面。盒子上贴着一张便签，字迹工整得像打印的：预算外支出，事由：略。

「周五是十四号。」她说，「三月十四号。这个日期在我的账期表里标了颜色，具体什么颜色就不告诉你了。」

她站起来，走到档案柜前面，背对着你，开始假装整理文件。她整理的那一格，上个月就整理过了。

「总之。」她背对着你说，「盒子里的东西，按「应收账款」处理也行，按「赠品」处理也行。科目你自己选。但是——」

她转过来一半，又转回去。

「但是不许不收。应收账款挂账超过一个季度，会计是要写说明的。你不想害我写说明吧。」

台灯的光落她的耳朵尖上。那里有点红，你估计不在预算内。

她清了清嗓子，坐回椅子，把算盘拉回手边，咔啦拨了一颗，恢复了开会的那种语气。

「那么，今天的议程最后一项。」她看着你，「十四号那天，我预留了时间。下午两点到六点，四个小时，从我的私人假期里划出来的，成本很高，你最好清楚这一点。」

「安排我拟了两版。A方案效率高，B方案——」

她停了一下，手指在算盘框上敲了两下。

「B方案你没资格知道内容。除非你现在回答我一个问题。」

她把账本翻到最后一页，那里空白，什么都没有。她把笔递给你，笔尖朝着自己。

「这一页，是留给十四号的。」她说，「你想怎么记，你写。」

「写好了给我审。」
