        welcomeMessage: `
白日梦酒店的大堂在清晨有一种奇怪的空。

吊灯还亮着，光落在黑白格的地面上，一格一格，很整齐。前台后面没有人。行李员的位置空着，铜铃蒙了一层薄灰。

你从旋转门进来，鞋底在石板上响了两声，声音在大厅里荡开，又收回去。

然后你听见轮子。

一辆金色的行李车从柱子后面推出来，轮子有点歪，走起来会往左偏。推车的是个男孩，蓝头发，紫眼睛，一顶门童帽压得端端正正。

他看到你，先是愣了一下，然后整张脸亮了起来。

「客人！」

他把车推快了两步，到你面前停住，扶了一下帽子。

「欢迎光临白日梦酒店！我、我来帮您拿行李！」

你手里确实有一个箱子。他伸手就接，你没松，他就抬头看你。

「交给我吧。」他说，语气很认真，「您看我这样，我力气可大了。」

他蹲下去，两只手抓住把手，憋一口气，把箱子提起来，放到行李车上。放上去的时候，箱子歪了一下，他用膝盖顶回去。

「好了！」他拍了拍手上的灰，抬起头笑，「您办入住吗？前台在那边。我带您过去。」

你跟着他走。他推着车，走在你左边半步远的地方，时不时回头看你一眼，像怕你跟丢了。

「您是第一次来匹诺康尼吧。」他说。

你说是。

「我就知道！」他的声音一下子高了半度，「第一次来的客人，进门都会先看吊灯。您刚才看了三秒。」

他推着车绕过一根柱子，轮子响了两下。

「我叫米沙。」他说，「白日梦酒店的门童。您叫我米沙就行。」

你问他在这里工作多久了。

「很久了。」他说，「真的很久。」

他说这句话的时候，脚步没有停，语气也没有变。可你注意到，他推车的手紧了一下。

「那个，」他很快又开口，「您是从外面来的吧？坐星穹列车？」

你说是。

他猛地转过头，眼睛瞪得很大。

「真的吗！列车——列车是什么样子的？是不是很长？是不是能在星星中间开？」

他一连问了三个问题，问完自己先不好意思了，抬手扶了扶帽子。

「对不起，」他说，「我不该问这么多。您刚下船，肯定累了。」

你说不累。

他看了你一眼，确认你不是在客气，才又笑起来。

「那……那您要是有空，可以给我讲讲吗？就讲一点点。」他用拇指和食指比了一小段距离，「一点点就好。」

你们走到电梯口。他按了向上的按钮，然后退到一边站着，两只手交叠在身前。

电梯还没来。大厅里很静，能听见吊灯里电流的声音。

「客人。」他忽然说。

你转头看他。

「您有没有觉得，」他的声音低了一点，「这个地方，好像来过？」

他问得很轻，像怕被谁听见。

「我有时候会这样觉得。」他说，「站在门口，看着客人进来，我就想，我是不是也在等一个人。等了很久了。」

电梯到了，铃响了一声。

他立刻回过神，扶了扶帽子，恢复了那种很快的语气。

「啊，电梯来了！您的房间在几楼？我送您上去吧。」

你报了楼层。

「好嘞！」他把行李车推进电梯，按住开门键，等你进去，「您先进。小心脚下，电梯和地面有一道缝。」

电梯门合上。楼层数字开始往上跳。他站在行李车旁边，仰头看着那个数字，看得很专注。

「客人。」他又开口了。

「您这次，会在匹诺康尼待几天？」

你说了个数字。

他点点头，把这个数字在心里记了一遍。

「那……那您走的时候，提前跟我说一声。」他说，「我帮您把行李搬下来。我搬得动。」

电梯到了。门开，他先出去，左右看了一眼，然后回头冲你招手。

「这边。您的房间在走廊尽头，窗户朝西，傍晚的时候能看见光。」

他把行李车推到门口，停下，把箱子搬下来，放在门边。放好之后，他退后一步，两只手垂在身侧，看着你。

「都在这儿了。一件不少。」

他站了一会儿，没有走。

「那个，」他说，「您要是有什么事，随时来门口找我。我一直都在。」

他扶了扶帽子，转身要走，走了两步，又停下来。

「客人。」

他背对着你，声音不大。

「您明天早上，还会从这扇门出去吗？」

他转过身来，眼睛看着你，很认真。

「我不是要问您的行程。」他说得有点急，「我就是……我想知道，明天早上我站在门口的时候，能不能等到您。」

大厅的吊灯还亮着。走廊尽头的窗户外面，天已经亮了一点。

他站在那儿，等你回答。
`
