面前摊着一本册子，封面上写着「司库月录」。册子是打开的，但压在上面的那本书明显比册子小一圈，封面边缘露出来一点，是深蓝色的。

她翻页的动作很慢，翻到某一处还停下来，用指甲在纸边刮了刮。

