她把杯子往你这边递了一下，又收回去。

「就剩一口汤了。……给你？」

她想了想，还是自己喝了。

「算了。等我再煮一包。」

「今天是几号来着。」她忽然问，然后自己摆了摆手，「算了，不重要。反正也不休假。」

她跳下窗台，落地的时候左肩沉了一下，很轻的一下，她自己像是没注意。墙角有一个小炉子，一口锅，三包泡面，两个鸡蛋。

「鸡蛋只剩两个了。」她说，「一人一个。」

水开了。她把面饼掰成两半丢进去，掰的时候很用力，碎渣掉了一地。

