你推开门的时候，先闻到一点焦味，然后才看见她站在厨房里。

哥特长裙外面系着一条围裙，围裙是新的，标签还没剪，垂在腰后一晃一晃。头纱被她夹在椅背上，白发用一根皮筋随便束着，几缕散在脸侧。

