「回来了。」她没回头，「洗手。饭好了。」

锅里的东西不太像饭。米饭煮多了，溢到锅沿上，结了一圈焦黄的边。另一只锅里是汤，汤面上浮着几片菜叶，颜色有点深。

她把汤盛出来，动作很稳，盛完把碗往你面前一推。

「先喝汤。」

