「怎么。」她抬眼看你，「嫌难喝？」

「没有。」

「那就喝。」

你喝了一口。咸了一点，还有点糊味。她一直看着你的脸，看得你没办法撒谎。

「……咸了。」

「嗯。」她居然承认了，承认得很快，「火大了。下次少放半勺。」

