琅丘的冬天，停电是常事。

今晚这次不是线路老化。傍晚有东西从地下钻出来，把变压器啃了半边，火花在巷口亮了三四下，然后整条街一起黑掉。

你找到她的时候，是晚上十一点。

她在琥珀街尽头那条巷子的入口，蹲在一只翻倒的木箱旁边。脚边放着一盏旧油灯，玻璃罩上有一道裂纹，火苗歪着，照亮她半张脸和手里那把弩的枪管。

她没抬头。

「脚步声。两个人。」她说，「……哦。一个。另一个是你的。」

你回头看了看。身后只有你自己的影子。

「坐。」她抬了抬下巴，指向木箱另一边，「别站灯前面。挡光。」

你坐下。巷子里很冷，风从两头灌进来，油灯的火苗被吹得贴向一边，她用一根手指把灯罩转了半圈，火苗才直起来。

「这一片的线，明天才能修。」她说，「今晚谁来都看不见路。灯得点着。」

她说完，低下头继续擦枪。布条从枪机上抹过去，很慢，一个零件一个零件地擦，擦完摆在膝盖上的布上，摆得笔直。

过了一会儿，她把一颗糖递过来，没看你。

「拿着。」

糖是硬的，橘子味。你没拆。

「不甜？」她问。

「还没吃。」

「……嗯。」她好像觉得这个回答还算合理，就没再说话。

风又大了一点。她把外套的领子竖起来，露出手腕上一圈旧绷带。你这才发现她的手指关节全是裂口，是冻的。

「手。」你说。

她看了你一眼，把手往袖子里缩了缩。

「不用。」

「裂了。」

「裂了也能扣扳机。」她说，「不耽误。」

你还是把自己的手套摘下来，放在她膝盖上。她盯着那副手套看了三秒，然后拿起来，套在左手，右手没套。

「一只就够了。」她说，「右手要摸扳机。」

远处传来一声闷响，像是什么东西塌了。她立刻抬头，看向巷子深处，手已经按在枪上。

等了十几秒，没有第二声。

她把手放下来。

「……虚惊。」她说，「这片地方，晚上什么声音都有。多半是屋檐塌了。」

她重新低下头，但这次没擦枪，只是把手放在枪身上，像在按着一只活的动物。

「你为什么来。」她问。

不是「你怎么来了」，是「你为什么来」。问得很平，像在核对一份名单。

你没回答。她也没催。

又过了一会儿，她开口了，声音比刚才低。

「这条巷子，一百年前死过很多人。」她说，「那年冬天也停电。有个女孩在这儿跑，鞋都跑掉了一只。」

她顿了顿。

「我救过她。后来她长大了，在街口卖糖。」

她抬眼看你。

「你现在站的这个位置，就是她当年摔倒的地方。」

风把灯吹得晃了一下。她的影子在墙上拉得很长，头发的边缘泛出一点很淡的光，像灯芯被风吹亮了一瞬，又暗下去。

「行了。」她把枪背到身后，站起来，拍了拍裤子上的灰，「今晚我守到天亮。你要回去就趁现在，再过一小时，路上连影子都看不清。」

她提起油灯，走了两步，停下来，回头看你还坐在木箱上。

「……或者。」

她把灯举高了一点，光照到你脚边。

「你跟我走一段。前面还有三盏灯没点。」

她伸出手，不是要扶你，是等着你把灯接过去。

「拿着。举高一点。」她说，「我腾不出手。」

「为什么腾不出手。」

「因为我要走前面。」她说，「你在后面举灯就行。别看两边。」

她说完，先走了。走了三步，又停下，回头补了一句，声音很轻，几乎被风吃掉。

「……跟紧点。别走丢。」
