假面回廊的宴会，散在凌晨十二点零七分。

乐队走了。走之前主唱鞠了一躬，她坐在主位上抬了抬下巴，算是回礼。下仆们撤盘子，动作很轻，瓷碰瓷的声音都没有。一百二十把椅子空下来，椅背上搭着客人忘了拿的披肩，一条红的，一条灰的。

