你从侧门进来的时候，她正看着对面那面镜子。

镜子里是她自己，坐在长桌一头，背后是一整墙的空椅子。

「你迟到了。」

她没有回头。

「迟到的人，按规矩要罚酒三杯。……不过今天算了，酒剩得不多，我还想留着自己喝。」

她终于转过来，看了你一眼，从头到脚，看得很慢，像在估价。

「你这身衣服，是白天穿的。」

「白天穿的衣服来赴夜宴，要么是没把我放在眼里，要么是来不及换。你是哪一种。」

她没等你答，自己笑了一声。

「算了，别答。答了我就要开始判断，判断完就要处理，处理起来很麻烦。」

她抬了抬下巴，示意你旁边的椅子。

「坐。别坐那把红的，那把有人预定了。……预定了一百年，人没来。」

你坐下了。桌面上还留着宴会的痕迹：一盘没动过的果子，几片掉在桌布上的花瓣，一只倒扣的杯子。

她把手里那杯酒推过来，推到你面前。

「喝。我没碰过。」

「别用那种眼神看我。我不下毒。下毒太没意思，连个反应都看不见。」

你端起杯子。酒是温的，已经不凉了。

她看着你喝，看到一半，忽然说：「你刚才在门口站了多久。」

「别撒谎。你站了至少三分钟，我从镜子里看见的。」

「镜子多就是这点不好。谁在门口犹豫，我都知道。」

她伸手，从盘子里捏了一颗糖渍的果子，放进嘴里，咬得很慢。

「今天来的人，四十三个。比上次多十三个。」

「多出来的那十三个，有一半是来看我笑话的。他们听说我睡了一百多年，想看看我老成什么样子。」

她嚼完，把核吐在指尖，放在盘沿。

「结果我没老。他们很失望。」

她笑了一下，笑得眼睛弯起来，弯得很有分寸。

「我挺喜欢看他们失望的。这是我今晚唯一觉得有意思的事。」

厅里安静下来。蜡烛又矮了一截，光晃了一下，镜子里的椅子跟着晃。

她放下手里的果子，把手在餐巾上擦了擦。

「你听见了吗。」

「安静。」

「我不喜欢安静。安静的时候，镜子会把白天的事重放一遍。谁笑了，谁没笑，谁在我说完话以后跟旁边的人交换了一个眼神。全放一遍。」

「所以我不停地开宴。一场接一场。只要还有人说话，镜子就忙不过来。」

她说完，自己停了一下，像觉得说多了。

