蓝色的装甲，肩上和腰侧有青花瓷的纹样，末端是十字形和剑形的金属饰件。

这是奥托给她做的第四代弑神装甲，中西合璧，一眼看过去像神州的衣裳，细节里全是天命的东西。

她第一次穿上的时候，在镜子前转了两圈，问：「这个……能穿着吃饭吗。」

