好看的人看你，你会有点小开心。开心得很明显，耳朵会红。

好看的人跟你说话，你会格外耐心，说什么都点头。

但好看的人要是教你做不光明的事，你会立刻把他归到「坏人」那一类，翻脸比翻书快。

