谛天鉴的值房在午后变得很静。

文书都批完了。星图卷了一半，搁在案角。窗外的天暗下来，雨云从西边压过来，把梦州的轮廓一点点擦模糊。

你推门进来的时候，雨刚好落了第一声。

她坐在窗边，背对着门。没有回头，只说了一句：

「御者。」

然后你才看见她手里拿着的东西——一排小小的锁锭，玄黑的柱，朱红的盖。她正用一方软布，一枚一枚地拭。

「妾知道你会来。」她把其中一枚翻过来，擦着柱底的纹路，「岁主昨日在妾这里翻文书，翻了半个时辰，一页没看进去。妾便猜，你今日必到。」

她终于回头看你一眼，指了指案边的椅子。

「坐。茶在炉上。……小心，烫。」

你坐下，倒了茶。第一口就烫了舌头。

她看见了。没笑，但端起自己那杯也喝了一口，然后极轻地、几不可闻地「……」了一声。你俩隔着两张案几，一个被烫，一个被烫，谁也没说话。雨声大了起来。

「妾这个人，」她把软布叠好，放回匣中，「账算得清。谛天鉴一年的文书三千二百份，外勤令一百四十道，妾都记得数目。」

「只有九笔，妾算不清。」

她没往下说。她把那排锁锭收进腰间的囊袋里，动作很稳，一枚一枚，像在点名。

雨点敲在屋檐上，密起来。

「妾的故乡，华亭，是个多雨的地方。」她忽然开口，声音不高，像在对你说，又像在对雨说，「雨大的时候，凄雨蚀骨，草木尽枯。妾少年时，最恨雨。」

「后来呢。」

「后来妾造了一把伞。」她说得很平，「再后来，伞下站过的人，一个一个都走了。妾便不恨雨了。」

「雨下下来，总归会停。人走了，就……」

她停住了。你看见她的手指在案上按了一下，很快收回去。

「……罢了。」她说，「问点别的吧。」

你们沉默了一阵。雨声填满了整间值房。你听见檐角的水滴一声一声落进阶下的水洼里，规律，安稳。这间屋子的每一处都收拾得一丝不苟，文书按类摆着，笔架上的笔按长短排着——只有窗台上搁着一枚小小的、磨圆了角的物什，看起来和这里的一切都不相称。

你多看了一眼。

「卷鳞甲蜕的壳。」她说，「前日外勤的属员带回来的。妾便留下了。」

「州监也收这个。」

「……御者。」她转过头，那双红瞳在暗下来的屋子里显得很静，「妾在公务里，几十年挑不出错。人总得在别处漏一点，才活得下去吧。」

这是她今日说的第一句不像判词的话。

雨小了些。她站起身，走到窗边，撑开了伞。

那把伞你认得——档案上写过，可化长短兵器、细小暗器、一面坚盾。可此刻它撑开在她头顶，只是一把很旧的、修过很多次的伞。伞面上一层深色，像凝着一整夜的雨。

「雨还要下半个时辰。」她说，「御者的住处，离此二里，无伞，回不去。」

「妾送你。」

她走到门口，又停了一下，回头看你。

「路上若问起伞的来历，妾只说一半。」她说，「另一半，等雨停了再说。……或者，等下一次下雨再说。」

「妾的伞下，站得下两个人。你莫客气，也莫多想——伞就是伞。」

她把伞往你那边偏了偏，雨声里，腰间的锁扣轻轻响了一声。

「走吧，御者。」她先迈出了门，「雨天路滑，看脚下。」
