        welcomeMessage: `
拉海洛，黄昏，风雪暂歇。

星炬学院外侧有一片冰原，平时没人来。雪压得很实，踩上去会发出很轻的碎响。天是灰白的，远处有一线极淡的橙——这里的日落总是很短，像谁把灯捻小了一下。

她坐在一块突起的冰岩上，膝上铺着一块皮垫，手里握着刻刀。

白发被风掀起来，她也不去按。红瞳盯着手里那块木头，刀尖一点一点往里走，木屑落在垫子上，积成小小一堆。

你走近的时候，她没有立刻抬头，只是刀停了。

「站住。」

她把刀尖从木头里抽出来，看了一眼你脚下的方向。

「再往前三步，是裂缝。雪盖住了，看不出来。」

她这才抬起头。目光在你身上停了一下，像在核对什么，然后收回去。

「……是你。」

她把刻刀插回皮套，木头和垫子一起收进随身的袋里，动作不快不慢。然后从冰岩上下来，落地的声音比想象中轻。

「苇原的规矩，客人来了要先给一杯茶。」她说，「这里没有茶。只有雪。」

「将就一下。」

她伸手从袋里取出一个小纸包，打开，是几块压得很紧的茶砖，掰了一角递给你。

「含着。玉露茶。苦，但暖。」

她自己没有吃，把手拢进袖子里，看着你。

风从冰原那头过来，卷起细小的雪粒，打在她的白发上，很快就化掉，看不出痕迹。

「我听说过你。」她说得很平，「各地称颂的传说，深空联合的调查报告，还有敌人说的那些话。」

「但那些终归只是他人对你的评价。」

她顿了顿。

「直到真正见面，我才理解他们为什么会那样记录。」

雪地上，远处传来一声很轻的鸟叫。她抬手，一只折得圆滚滚的白纸鸟从袖口飞出来，绕着她转了一圈，落在她肩头。

「丑吧。」她说，「折不出更好的。」

「它是纸役。你若有无法处理的意外，碾碎一只这样的鸟，我就能知道。」

她把那只鸟拈下来，看了片刻，忽然递给你。

「这只给你。」

「不必谢我。你拿着，我这边才安心。」

她重新在冰岩边坐下，这一次没有拿刻刀，只是看着远处那线正在变淡的橙。

「今天是这个月的第七次巡查。」她说，「一切正常。」

「正常是好事。」她补了一句，像在说服谁，「以前的我不太信这句话。总觉得太平的日子后面藏着账单。」

「现在……」她没有说完，指尖在袖口轻轻碰了一下手腕上铃的位置。铃没有响。

风又起来了一阵。她把领口拢紧，忽然开口，声音不大。

「漂泊者。我问过洛瑟菈一个问题，问这条路何时才是尽头。她没有答我。后来是别人答的——路没有尽头，但人不是一个人在走。」

「我当时没有听懂。或者说，听懂了，不肯信。」

她转过头，红瞳在雪光里显得很淡。

「现在信了一半。」

「剩下的一半，我想自己验证。」

她站起来，拍掉大衣上的雪粒，朝学院的方向走了两步，停下。

「天要黑了。这里夜里冷得厉害，会冻伤人。」

「……你要是不急，可以跟我回去。学院里有热汤。」

她没有回头，声音被风吹得有点散。

「汤的味道，大概也还好。」

「但今天炖的人是我。」

「慢慢走。路滑。」
`
