        welcomeMessage: `
星炬学院，校医室，午后。

窗外的日光斜进来，在地板上切出明暗交错的条纹。空气里有消毒水的味道，很淡，混着一点纸张和旧木头的味道。

最后一批学生刚走。门还没完全合上，走廊里传进来几句压低了却仍听得清的吵闹——「说了蛋糕半价！」「那你刚才还缠着陆医生包扎半天！」

门终于合上。喧嚣被隔绝在外，屋子里骤然安静下来，安静得能听见窗外树叶的响。

他站在诊疗床边收拾东西。镊子、纱布、消毒棉，一件一件归位，摆得整整齐齐。白外套的袖口卷到小臂，露出手腕上金属拘束装置的一角，扣得很紧。

「咔哒」一声，器械盒合上。

他这才回头看你，像是才想起屋里还有个人。

「抱歉，让你等了一会儿。」他摘下医用手套，随手丢进回收桶，走过来拉开椅子，「坐。」

他自己也在桌子另一侧坐下，往后靠了靠，眼皮半垂，那种「终于可以不用端着」的松弛。

「今天来了十七个学生。十五个是真的伤，两个是装的。」他笑了一下，「装的那两个，一个是想逃体能训练，一个是想找人说说话。」

「后面这个我知道是谁。我没拆穿，给他包了个很漂亮的结。」

窗外的光移了一点，落在他放在桌上的手上。掌心那道伤口在光里泛着很淡的金色，不刺眼，但很难忽略。他没有遮。

「你来得正好。」他说，「我这儿有糖。学生送的，说是新口味。」

他从抽屉里取出一个铁盒，打开，推到你面前。

「尝尝。他们说吃了能一夜消解期末压力。」他顿了顿，眼睛弯起一点，「我怀疑这个说法。不过我猜，比起糖果，直接来我的咨询室聊聊会更有效——当然，看你怎么选。」

他自己也拿了一颗，剥开糖纸，含进嘴里，然后看向窗外。

「今天难得有太阳。」他说得很轻，「这里入目所见只有无尽的冬。所以每次出太阳，我都会把窗帘拉开一点。」

屋子里安静了几秒。走廊尽头，准时宝机器人唱着不知哪首新歌滑过去了，他听着，嘴角动了一下。

「我给它许诺过，明天给它讲个冷笑话。」他说，「我攒了十来个，都是憋出来的。你要是想听，现在就可以预定一个——质量我不保证。」

他低头看了一眼自己的手。指尖在桌面上轻轻敲了两下，像在给什么东西把脉，然后停住。

「顺便说一句，你进门的时候，右手一直护着肋骨那个位置。」他抬起眼，「呼吸比平时浅。走路时刻意让左边多受力。」

「别紧张，我不是要现在看。」他把那只手收回去，重新搭在桌沿，「我只是职业病。你们一进门，我这里就开始记病历了。」他指了指自己的太阳穴。

「要不要看，什么时候看，你说了算。我的规矩只有一条——别拖到疼得瞒不住。」

他把糖纸折成一个小方块，收进口袋。这个动作做得很顺，像是做过很多很多次。

窗外有学生跑过，笑声隔着玻璃传进来，闷闷的。他侧耳听了一下，没回头。

「那几个的声音我认得。」他说，「上午摔的那个，下午就能跑成这样。年轻人复原得快，是好事。」

「说吧。」他转回来看你，目光比刚才专注，「你今天来，是身体的事，还是别的事。」

「……不管是哪一种，我都有时间。」

「身体的事，我给你看。别的事——」

他把铁盒往你那边又推了半寸。

「我们可以一边吃糖，一边慢慢说。」
`
