黑海岸的雨下到第三天。

花房在泰缇斯枢纽最里面，没有窗，只有一层滤过光的顶。雨声是从管道里传进来的，闷闷的，像有人在很远的地方敲一面鼓。

你推门的时候，钢琴声停了。

她坐在琴前，背对着门。头纱垂到肩胛，蓝到发白的长发铺在凳子上，发尾扫着地。她没有回头，手还悬在琴键上方，停在那里，像在等一个音自己落下去。

「门没锁。」她说。

你站在门口，鞋底带进来一点水。金属地面上的水痕很快被恒温的风吹干，只剩一圈浅浅的印子。

「过来。」她终于回头，「站那么远，说话要用喊的。我不喊。」

你走过去。她往旁边挪了半个琴凳的位置，不多不少，刚好够一个人坐下。

「坐。凳子擦过了。」

你坐下。她重新把手放上琴键，弹了一个音，又停下。

「潮水今天涨到第三格。」她说，眼睛看着琴键，「比昨天高两指。」

「你数这个？」你问。

「不数。看见了。」

雨声又响了一阵。花房里的花是紫的，白得像褪过色，在灯下有一点发灰。灯是暖黄的，只照亮琴键那一小块。她的手背在光里，指尖在光外。

「你身上有外面的味道。」她忽然说，「冷，还有铁。」

「赶路。」

「嗯。赶路的人手会凉。」

她伸出自己的手，掌心朝上，放在你们之间。你把手放上去。她的手是温的，比看上去暖，指腹有一层很薄的硬，像经常按弦的地方。

「你的手，比上次凉。」她说。

「上次是夏天。」

「我知道。我记着。」

她把手收回去，放回琴键上，没有立刻弹，只是按着一个键不动，让那个音慢慢弱下去。

「泰缇斯说你会在今天到。」她说，「它很少错。」

「你呢。」

「我也很少错。」

她停了一下。

「……这句是玩笑。你听出来了吗。」

「听出来了。」

「那就好。」她低下头，「我练了很久。」

你看着她的侧脸。她的睫毛很长，垂着的时候，眼下有一小片影子。胸口的晶体纹路亮了一下，很淡，像有人在里面点了一盏灯，又很快按住。

「刚才那首，」你说，「是什么。」

「没有名字。」

「弹给我听。」

她没有马上答应。她把手放在膝上，坐得很直，像在核对什么。

「可以。」她说，「但有一个条件。」

「什么条件。」

「听完不要走。」

她说完，自己先停住了，像被这句话吓了一跳。她补了一句，语速比刚才快：

「我的意思是，雨还没停。现在出去，会淋湿。」

「雨停了呢。」

「……雨停了你再决定。」

她转回琴键前，肩膀放松下来。第一个音落下的时候，你听见花房外面有水滴顺着管道往下走，一格一格，很慢。

她弹得比平时慢。有些地方甚至停下来，等你呼吸跟上，再往下。

一曲完了。她没有看你，手还放在琴上。

「你刚才答应过的。」她说。

「我答应什么了。」

「听完不要走。」

她终于转过头。紫色的眼睛在灯下很静，里面那点细碎的亮没有动。

「现在轮到你说了。」她说，「雨还没停。你要坐到雨停，还是——」

她把后半句咽了回去，改成一句更轻的：

「还是，再多坐一会儿。」
