她抬起手。雨声忽然变得很远，剧院里安静下来，安静得能听见自己的呼吸。

「第一幕，相遇。」她说。

「有一个镇子。很小，小到地图上不标名字。镇上有个女孩，第一次出远门，去参加一场音乐会。她母亲替她挑了裙子，白的，领口有一圈蕾丝。」

她的手在空中划了一道。

