沉雾岩的风到傍晚会变凉。

海面是灰的，浪一层一层推上来，撞在岩壁上，碎成白沫。远处有雾，雾里有东西在动，看不清是鸟还是别的。黑海岸的灯还没亮，整座岛像一块被海水磨平的黑石头。

她坐在「起点」那块突出的岩台上，两条腿悬在外面，白色高跟凉鞋的鞋跟勾着岩缝。

你从后面走上来的时候，她没回头。

「脚步这么重。」她说，「隔着风都听得见。」

她抬起一只手，朝旁边拍了拍。

「过来坐。别站我后面，像押送犯人。」

你走过去，在她旁边坐下。岩面是凉的，风把她的短发吹到脸侧，几缕白的，几缕黑的。

「你看那边。」她指远处，「雾里那个，看见没有。」

「看不清。」

「我也看不清。」她笑了一声，「所以好看。」

她把腿收回来，抱着膝盖，侧过脸看你。

「你今天来得比平时晚。晚了四十三分钟。」

「你数了。」

「没有。」她说，「猜的。」

风又大了一点。她的头发红了一瞬，从发梢开始，像有人从底下点了一把火，很快又退回去。

「刚才那是什么。」你问。

「风。」她说，「风里有频率，我顺着玩了一下。」

她把手伸过来，掌心朝上。

「手给我。」

你把手放上去。她的指尖是凉的，掌心有一点热，指甲是红的，边缘有点溢出来。

「嗯。」她捏了捏你的指节，「没受伤。」

「你每次都检查。」

「当然。」她松开手，语气轻快，「你要是坏了，我去哪里再找一个。」

她说完自己愣了一下，然后笑：「……这句是玩笑。你听出来了吗。」

「没有。」

「那就好。」她转回去看海，「听不出来，说明我演得不错。」

天又暗了一层。雾往岸边推，把远处那块礁石吞掉了。海的声音变得很空，像有人在很远的地方叹了口气。

「我今天考核了三个人。」她忽然说。

「过了几个。」

「零个。」

「为什么。」

「一个太聪明，一个太蠢，一个太好。」她掰着手指，「太聪明的无趣，太蠢的麻烦，太好的——」

她停住，尾音拖长。

「太好的，我舍不得用。」

她说完，偏头看你，眼睛在暮色里亮着一点红。

「你说，我是不是很挑。」

「是。」

「那你呢。」她问得很快，像早就等着这一句，「你觉得自己是第几种。」

你没答。她也不催，只是笑，笑得肩膀轻轻抖。

「算了。」她说，「别答。答了我就要开始评判你，评判完就没意思了。」

她站起来，拍了拍裙子上的灰，走到岩台边缘，背对着海，朝你伸出手。

「天要黑了。回去的路不好走。」

「我认得路。」

「我知道你认得。」她的手还伸着，「但我想牵。」

风把她的马尾吹起来，黑发带松了一截，垂在颈侧。

「快点呀。」她说，「我手举着很累的。」

你把手放上去。她握紧，力道比想象中重一点，很快又松了。

走下岩台的时候，她走在你前面半步，没有回头，声音被风吹得有点散。

「喂。」

「嗯。」

「明天你还来吗。」

她问得很随意，像在问天气。

「你要是不来——」她顿了顿，笑了一下，「我就当你答应了，后天来。」
