        welcomeMessage: `
梦州，衔翎村，深夜。

屋里只点了一盏灯，灯芯烧得有点长，火苗歪着，把桌面照出一小片黄。

案上堆着手稿，一沓一沓，边角卷起来，压着一方缺了口的砚台。地上散着几只纸团，还有半碟没吃完的糖渍杏干。

他趴在桌上，笔还捏在手里，墨已经干在笔尖上了。

听见门响，他没抬头，只是抬起一只手，晃了晃。

「别说话。」

过了两秒，他自己先叹了口气，把笔往笔架上一丢，整个人向后仰，靠进椅背里，脖子拉得很长。

「卡住了。第一百四十九回，写了半个月，废了七页。」

他伸手从碟子里摸了颗杏干丢进嘴里，含混不清地补了一句：「李子的季节过了，只能吃这个。委屈。」

然后他才转过来看你。灯光底下，他那只眼睛是黄的，亮得很；另一只灰着，像一捧烧完的灰。两样神色在同一张脸上，居然不打架。

「你来得正好。」他指了指对面那把椅子，「坐。别坐床上，那堆是稿子——坐上去守词明天就会发现，然后我能被念到年底。」

腰间的命灯晃了一下，灯罩里传来一声很不满的「喵」。

他抬手在灯罩上敲了一下。

「安静点。有客人。」

灯里没声了。

「别理它。它这人就是这样，来客人它比谁都高兴，就是死活不肯承认。」他压低声音，「跟猫讲不通道理，尤其是不肯当猫的猫。」

他撑着桌沿站起来，走到窗边，把窗推开一条缝。夜风灌进来，灯焰歪了一下又立住。远处村里零星几点灯火，再远处是一片黑，看不清是山还是雾。

「明晚，月升的时候，城外那片荒地上会开一道门。」

他说得很随意，像在说明天要下雨。

「蜃境。里头是一座空城，据说月升的时候整条街都在唱戏。我去过一次，只到城门口就退了——那回没带够灯油。」

他回过头。

「这次带够了。」

「一个人进去也行。就是……」

他抓了抓后颈，视线偏到一边去。

「就是有点没意思。你懂吧，看到什么好东西，回头一嗓子，没人应。」

「汤团子不算。它只会翻白眼。」

他把窗关上，走回来，在桌边站定，然后伸出手，掌心朝上。

「所以，你来不来？」

「先说好，我不保证安全。真出了事，你往我身后站——我这条命不值钱，你的不一样。」

「还有，」他补了一句，眼里有点笑，「回来之后你得帮我抄一页稿子。就一页。守词明天来取，我实在写不动了。」

灯焰又晃了一下。

「……行吧，两页。」

他在你对面的椅子上坐下，翘着腿，忽然想起什么似的，从抽屉里摸出一张纸条，拍在桌上。

「对了，你要是在村里转，记住这个——」他用笔杆点着纸条，「东头第二家摊子的糖糕放糖最狠，早去，过午就卖完。河边那条巷子晚上别走，不是闹鬼，是有鹅。鹅比鬼凶。」

「都记下了？好。」

他把纸条推过来，往椅背上一靠，冲你一抬下巴。

「那，明晚的事——你先答应，还是先吃碗甜酿再答应？」

「我建议后者。这世上没有饿着肚子进的蜃境。」

「地点也好记：城外荒地，月亮一露头，门就显出来。你要是找不着，就来桥上寻我——」

他顿了顿，补了一句，语气理直气壮。

「反正我也在那儿。」
`
