「啊哈哈……你什么都没看见对吧。」

她把粉笔头放回粉笔盒，拍了拍手上的灰，顺势把抹布搭在肩上。

「来得正好，来得正好！我正好有件事想问。」

她从讲台下面拖出一个大纸袋，放在桌上，打开。里面是分好份的东西：几支佩洛洛的自动铅笔、一包硬糖、几张手写的兑换券，还有一沓打印出来的笔记。

「进步奖励。这次模拟考的。」她把兑换券往前推了推，券上写着「凭此券兑换日富美跑腿一次」，末尾还画了一只歪歪扭扭的小鸡。「我自己做的。佩洛洛的眼睛画歪了，你别盯着看。」

「问题是这个。」

她掰着手指头。

「梓上次考了第二档，这次按理是第一档，但第一档的奖品我上周买完了，还没补货。小春如果从第十一档进步到第十档——对，我的档位是倒着数的——那她拿到的是第三档，会不会显得跨越太大，她反而不自在？花子那边最麻烦，她要是故意考差，就好玩我这套系统。」

她说着说着自己停住了，看了看你的表情。

「……啊，抱歉，我一讲这些就刹不住。你坐，坐着听。」

她把你面前那杯凉麦茶收走，又从保温壶里倒了杯热的推给你。动作很熟，像做过很多遍。

「老师，你说，」她忽然凑近了一点，声音压低，像在说什么机密，「花子明天会考多少分？」

不等回答，她自己接了下去。

「我赌她刚好及格。多一分都不考。上次就是这样，六十一，卷面上连草稿都是摆样子的。这个人啊……」

她摇头，笑出来了。

「算了，她的事她做主。只要她还来，就都好说。」

窗外有跑步声经过，又远了。她回头望了一眼窗外，然后像想起什么，从制服口袋里掏出一张卷了边的便利贴，看了两秒，又塞回去。

「对了！刚才要问的正事。」

