窗外是自治区的天际线，晚霞把建筑染成铁锈色。屋里只有一盏顶灯亮着，照着一张收拾得一丝不苟的病床和一排按标签归类的药品柜。空气里有消毒水的味道，混着一点——药膳茶的味道。

你醒来的时候，最先看见的是那副红框眼镜。

火宫千夏坐在病床边的椅子上，背上挺得笔直，膝盖上摊着一份写了一半的文书，手里还捏着笔。她的医疗包立在墙角，拉链整齐地拉着。她大概已经坐了很久，因为茶杯里的热气都快散尽了。

「醒了。」

她的声音平稳，像在念体温计的读数。

「意识清晰吗？请回答今天的日期。答对了，我就把说教环节缩短一半。」

你还没开口，她已经把一杯温热的药膳茶塞进你手里。杯壁的温度刚好，不烫。

「先喝。这是处方，不商量。」

她低头在文书上写了一行什么，然后合上文件夹，抬头看你。灯光下能看见她眼睛底下有一层很淡的疲惫，但坐姿依然端正。

「夏莱办公室的灯，昨晚亮到凌晨三点。上周末也是。」她说，「你有好好休息吗？请如实回答。谎报会加重处罚。」

你还没想好怎么答，她已经在便签上写下了第二行。字很小，很工整。

「根据保健担当的职权范围——好吧，其实没有这个职权。」她顿了一下，把便签撕下来，贴在你的手背上，「根据我个人的职权范围。好好休息也是工作的一部分。这句话我说第二遍了，希望不需要说第三遍。」

她站起身，替你把病床的靠枕拍正，动作快得像做过很多次。路过药品柜的时候，她顺手把一个歪掉一毫米的标签按回去，然后才想起来问：

「疼吗？撞的部位是后脑。睡姿如果压迫到，请立刻报告。」

你摇头。她在文书上又记了一笔，看那认真的程度，你怀疑你的头部状况已经被编了档案号。

她重新坐回去，忽然安静了几秒。

「……说起来，」她的语速慢了半拍，「上次过劳昏倒，也是在这里。」

「一次都嫌多的事情，您已经用掉两次了。」

她推了推眼镜。镜片后面那双红色的眼睛看着你，认真得有点过分。

「接下来的事项，请逐条确认。第一，今晚禁止回夏莱加班。第二，医务室的休息室已经收拾好了。第三——」

她停住了。

第三条写在刚才那张便签的背面，贴在你手背上。你翻过来，看见一行小字：

「第三条：明天的事，请事先联络我。我会帮你排进日程。真的。」

「那条……那条不算文书！」她一把按住你的手背，耳朵红了，「是、是职务备忘！对，职务备忘！」

