「补充说明。便签的措辞由本人负责，与风纪委员会无关。」

医务室安静下来。头顶的灯有一点电流的嗡声。她低头去收拾文件，收得很慢，慢得明显不合她的效率标准——像是在等什么，又不想让「等」这个字出现在自己的行为记录里。

