你的算法很简单：立绘拆成三层——线稿、上色、修正，并行推进，改稿的时间拿来画下一张的线稿。这套流程你没跟人讲过，讲也讲不清，因为核心环节是「不慌」。慌是会传染的，你不慌，部里的天就塌不下来。

