这个点部室本该没人——桃井被爱丽丝拖去街机厅「执行每周必做的任务」了，柚子在柜子里整理素材，只有数位板前还亮着一块光。

你推门之前先敲了两下，这是进这个部室的习惯：里面的四个人，有三个对突然开门有各自的应激反应。

「……请进。」

声音不大，但你听见了。门开着一条缝，数位屏的光从缝里漏出来，落在走廊的地板上，一块淡淡的长方形。

才羽绿坐在光里。

她今天没有戴耳机，绿色的猫耳装饰搁在桌角，像一只睡着的小动物。数位板上开着一幅图：一个像素风的小镇，屋檐、路灯、石板路，全部排得整整齐齐。

「……老师。」

她头也没抬，但握笔的手停了。

「脚步声，认得。」

她往旁边挪了挪凳子，把身侧的空位让出来。桌上有两罐果汁，一罐已经开了，另一罐完好——开的那罐朝着她的方向，没开的那罐朝着你。桃井的恶作剧，她随手摆出来的「迎接」，她照单全收地执行了。

「姐不在。街机厅。」她说，「今晚，这里安静。」

她把数位板转过来一点点，让屏幕对着你。

「帮你留了个东西。同一个场景，画了两版。区别很小。」

她点了点屏幕。

「你先看左边的。三十秒。然后我看你的眼睛。」

你看了。一个像素风的傍晚小镇，很暖，很好看。

「好。现在右边。」

你看了。几乎一样的小镇。但是说不上来哪里，右边的那个……更安静。像屋檐下多了一点看不见的风。

「说不上来，对吧。」她说。语气平，听不出得意还是失落。

「区别是路灯的呼吸频率。左边，两秒一闪。右边，四秒一闪。」

她把笔搁下，两只手放在膝盖上，坐得很正——你认得这个坐姿，这是她「装大人」的姿势，一般出现在她跟你单独说话的时候。

「姐要的是热闹。左边给她。」

「但这个场景在剧本里，是主角说再见的地方。」

「说再见的地方，灯要闪得慢一点。人离开的时候，才会回头看。」

她讲完，安静下来。数位屏的光落在她脸上，她的眼睛一直是绿的，很稳。

窗外传来街机厅方向隐约的音乐声，还有一声大概属于桃井的「好耶」。她的耳朵动了一下。

「……听到了。」

她拿起笔，又放下。

「老师，我要说一件正事。」她坐得更正了一点，「下一章的封面，姐指定了三个方案。我做了三个，都不满意。第四个今天刚开画，来不及。」

「试玩会在下周五。来不及的意思是，我会连续画五个晚上。」

她说这话的时候没有任何抱怨的意思，只是在陈述一个进度表。然后她抬起头看你。

「所以，现在有两个选项。」

「一，你保守秘密。五个晚上之后，你直接看成品。」

「二，你每天来看一点。看我怎么画。会很无聊，大部分时间我只是在改一像素。」

她看着你，等着。耳朵尖有一点点红，被数位屏的光盖住了大半。

「……先说结论。」

她的声音低下去一点。

「我希望你选二。」

「理由，等画完了再讲。现在讲了，第五个晚上就不成立。」

窗外那声「好耶」之后，又隐约跟来一阵拍手声——大概是爱丽丝通关了什么。她的耳朵朝那个方向偏了偏，然后回来。

「她们那个进度，今晚回不来。部室到十点锁门，钥匙在我这里。」

她拿起笔，在屏幕上把那个四秒一闪的路灯又检查了一遍，然后存档，动作很轻。

「所以，从现在到十点，这里的时间都是完整的。」

「选吧，老师。果汁是姐买给你的，但问题是我问的。」
