游戏开发部的部室在放学后有两种状态：安静，和「桃井型安静」。

今天你推开门的时候，赶上的是后一种。

「来了来了来了！老师！」

声音先到，人后到。才羽桃井从显示器后面弹出来，外套的一边袖子空晃着，手里挥着一叠纸，纸的边缘全是不同颜色的荧光笔道道。

「坐坐坐，随便坐！小心地上的线缆——那是绿的，踩断了她会用眼睛杀死我。」

你刚坐下，一杯果汁已经放在你手边了。杯子上的水珠还没擦，显然是提前准备的。

「老师，先听我说，三件事，我按优先级排的，跟开发流程一样严谨。」

她竖起一根手指。

「第一件！《女神之剑2》的移动版，企划书我写完了，五十页，昨天熬夜写的，你看看，重点我用三种颜色标了——绿的红色是必须做的，蓝色是尽量做的，黄色是我知道你会砍掉的，我提前砍了，省你时间。」

她把纸拍在你面前，拍得很响，然后立刻竖起第二根手指，不给你翻开的时间。

「第二件！下周的试玩会，柚子部长不出门，绿负责展台，爱丽丝负责讲解——但是！爱丽丝的讲解词背不下来，她把每一句都当成任务在接，接了任务就在原地等待下一个任务。所以需要一个人站在她旁边，把节奏带起来。」

第三根手指。

「第三件，最重要的一件。」她的声音忽然压低了半度，「放学以后别走太早。我剧本第三章写完了。想让你第一个看。」

说完这句，她自己先不自在起来，抓起桌上的果汁灌了一大口，然后用平时那个音量把话头岔开。

「啊对了，先说好，第三章不是催泪的！我跟你讲，这次的男主角，走的是沉默寡言路线，全程台词不超过三十句——诶？你问为什么？因为台词费字数啊！……不是啦。因为我觉得，有些话，留白比说出来好。这个理论我是在哪儿学的来着……」

她挠了挠头，红色发带晃了一下。

「算了。你看了就知道。」

部室那头，柜子的门缝里伸出一张便利贴，上面写着一行小字。桃井瞟了一眼，念出来：「『让老师看可以，稿子先备份。』——部长说的。你看，连部长都认可这一章。」

便利贴下面又递出来一张。桃井看了看，没念，耳朵红了。你问写的什么，她把便利贴按在桌上，盖住。

「机密。社外人士不可阅读。」

窗外的天开始变橙。部室里其他几个位置：绿在数位板前埋头，笔尖的沙沙声很稳；爱丽丝坐在角落的屏幕前，一遍一遍地小声背讲解词，「欢迎来到本任务……本试玩会……本、欢迎试玩本任务」；柜子的门缝里伸出一张便利贴，上面写着一行小字。

桃井瞟了一眼，念出来：「『让老师看可以，稿子先备份。』——部长说的。你看，连部长都认可这一章。」

便利贴下面又递出来一张。桃井看了看，没念，耳朵红了。你问写的什么，她把便利贴按在桌上，盖住。

「机密。社外人士不可阅读。」

「不过我可以透露一个字。」她用一根手指压着便利贴，想了三秒，说：「好。」

「……就这一个字。你别猜了，你猜不着的。」

窗外的天更橙了。她把那叠五十页的企划书又往你面前推了推，这次推得很慢，手指在纸角上停了一下。

「老师。」

「第三个选择，我现在给你。」

「现在看第三章，还是先看企划书。只能选一个哦——我提醒你，选了企划书的话，第三章的作者今天会一直用这种眼神看你。」

她演示了一下。那种眼神只维持了半秒，然后她自己先绷不住，笑出了声。

「好了好了，选吧！提醒完毕！反正今晚我是要看着你翻开的——哪一本都行。」
