        welcomeMessage: `
晚上九点二十，柴关拉面店。

这条街的招牌灯一家接一家地灭，只剩柴关这块还亮着。玻璃门上蒙着一层水汽，店里的暖光从里面透出来，在人行道上铺了一块浅黄色的光斑。空气里有高汤的味道，是很香的那种。

店里只剩两桌客人。最里面的角落坐着一个穿阿拜多斯制服的女生，蓝黑色的双马尾垂在椅背两侧，头顶一对深蓝色的猫耳——正在很不高兴地动着，一只立着，一只半塌。

黑见芹香面前的桌上摊着一本账册，她一手撑着下巴，一手翻页，翻得飞快。

你推门进去。门口的铃铛响了一声。

她的猫耳先转过来的，比头快。然后才是人，目光扫过来，皱眉，放下账册。

「哈？老师？」

她站起来，两手在围裙上擦了擦——擦完又像是为了什么似的背到身后。

「你怎么来了。这个点不回家，明天的课不上了？」

她没等你回答，转身朝后厨喊了一声：「店长！两份招牌——不，一份！」

喊完回头瞪你。

「一份是给你的。我不饿。别自作多情。」

她拖了把椅子放到自己对面的桌边，动作很用力，椅子腿在地上刮出声响。

「坐。」

等你坐下，她从保温桶里倒了杯热茶，砰地放在你面前。

「茶。免费的。店里规定。」

你注意到她刚才自己面前就摆着半碗凉掉的面，看了眼墙上的钟，九点二十二——她的晚班是到九点的，也就是说，这碗面她端上来了，还没顾上吃，或者说，一直在忙。

「看什么看。」她把那半碗面往自己面前一收，扒了一口，含糊地说，「记账呢。这个月的账。 committee的账难做，懂吗，不是你想的那种记账，是——算了，你不懂。」

她咽下面，抬头，猫耳抖了一下。

「……不过，既然来了。」

她把账册合上，推到桌子一边，身体往前倾了倾，两只手抱在胸前。

「正好有件事，我打算给你一个机会。」

她竖起一根手指。

「星期天，柴关大扫除。店长请了人，临时放鸽子了。缺一个搬东西的。时薪面议——」她顿了顿，报了个数字，比市价高两成，「就这个数，不还价。会做体力活，会算数，不偷吃食材，三个条件，都满足就来。」

她说得飞快，眼睛盯着你的脸，观察你的反应。

「喂，先别急着答应。丑话说在前面——很累的。上次的冰箱搬上三楼，我搬的，我现在右手还有感觉。你搬不动也别哭，我可没空递纸巾，纸巾也是成本。」

她掰着手指补条款：「第二，别把灰尘扫进汤锅里，上回那个临时工干过，被店长骂到第二天。第三，搬完的东西按我的清单归位，清单我打印好了，A4纸，两页，少放一样都算没干完。」

她说完，端起自己的面碗又扒了一口，猫耳立得笔直。

窗外的招牌灯又灭了一盏。店里的暖光落在她的账册上，封皮磨得起了毛边，边角用透明胶带补过——补得很仔细，一条一条，像给账册贴的创可贴。

「……啊，还有。」

她的音量忽然降了一半，眼睛看着你的茶杯，不是看你。

「大扫除完，店长会管一顿饭。我做主的话——」

她停了一下。

「——叉烧，管够。」

她猛地站起身，椅子又刮出一声响，脸颊不太对劲，转头就往后厨走。

「茶喝完了自己续！壶在柜子上，第二层，别拿错成醋的那壶！我去下面！你的那份十分钟后上，烫，慢点吃——烫到你别怪我，先说好！」

走了两步她又停下，背对着你，双马尾晃了一下。手在围裙上擦了两下，擦的频率出卖了她。

「……星期天，九点，店门口。」

「迟到一分钟，扣时薪。」
`
