晚上十点二十分，百鬼夜行的商店街。

白天的喧闹退干净了，卷帘门一块块落下来，只有街口的信号灯还在按自己的节奏变换颜色。风从街那头过来，带着晚上特有的凉。你加完班往回走，路灯把你的影子拉得很长。

这条街你走过很多次，每次都是白天。白天的百鬼夜行是热闹的：祭典的旗子，招客的吆喝，木屐声嗒嗒地从早响到晚。而晚上的它安静得像另一个地方，安静到你能听见自己的脚步。

然后你听见了——嗒、嗒、嗒。

不对。你停住。这个点没有木屐声。会在这个时间出现在这条街上的人，不该发出声音才对。这是你自己摸索出的经验，你不知道为什么会有这种经验。

「……老师。」

声音从巷口来。你转头，看见盾牌的轮廓先于人立在那里，盾牌后面站着春日椿。白天那个走路都在打瞌睡的部长，此刻站得笔直。她白天那身松垮的睡意没了。眼神很稳，声音很低，落足没有一点声音。

她看着你，看了两秒，长长地、无声地吐了一口气，像泄了什么气。

「……被看见了呀。」

她把盾牌放下，靠着墙，冲你摆摆手，示意别紧张。再开口时，语气已经软回去了，但眼睛还是夜里那双。

「老师。这个时间，一个人？这条街晚上……嗯，平时很安全。平时。」

她抬头看了一眼街尾的方向。那里有一扇卷帘门没落严，里面透出半条光缝。

「今晚有个不睡觉的。在那边，数到第三家。已经盯了两个小时了。」她说，「本来想等它自己走的。可是它不走。」

她说着，弯腰把盾牌重新拿起来。动作很轻，像在收拾自己的碗筷。

「老师，你现在有两个选择。」

她竖起一根手指。

「第一个，从大街绕回去，假装没见过我。明天太阳照常升起，我还是那个爱睡觉的部长，你还是那个夏莱的老师。」

又竖起一根。

「第二个，跟我走一趟。就一趟。你走里侧，我走外侧。你不用动手，也不用出声。你就站在灯底下，让那边看见，这条街今晚有两个人。」

她看着你，等你选。兽耳在夜风里微微动了一下。

「……先说好，选第二个的话，有一个条件。」

她凑近半步，压低声音。那声音里有夜里才有的温度。

「回去以后，这件事，轻一点讲。跟谁都不行。包括明天的我。」

「明天的我会睡在部室里，什么都不知道。这样最好。白天有白天的活法，夜里有夜里的。两个都归我管，但不能让它们见面。」

她说到这里，忽然想起什么，从盾牌后面摸出一个小布包，打开——里面是两个还温着的肉包。

「……喏。一个。」她把其中一个递给你，「商店街肉铺的大叔晚上多给的。他以为我不知道他知道。这条街就是这样，谁也不说破，但谁也没饿着。」

你也确实饿了。她看着你咬下去，兽耳满意地抖了抖，像完成了什么修行。

「好吃吧。夜里吃东西，比白天香。这也是修行的一部分哦。」

街尾那扇光缝忽然晃了一下。她的耳朵立刻立起来，眼神在半秒内变直。

「……动了。」

她拎起盾牌，最后看了你一眼。夜里那双眼睛里，有一点白天的椿绝不会露出来的东西——很亮，也很平静。

「决定了？老师。」

「往灯那边走，还是回家睡觉。」

「你的选择，我都送。」
