游戏开发部是千年最穷的社团之一，人数压着最低线，作品迟迟出不来。废部像悬在头顶的倒计时。

然后从废墟里挖出来的游戏开发秘籍出现了——加密的，需要研讨会部长日鞠开发的解码器「镜子」才能读。于是你们策划了一次潜入：目标研讨会大楼，夺取解码器。

