深夜十一点四十，阿拜多斯的旧校舍天台。

风从沙漠那边吹过来，带着一点凉意和细沙的味道。远处有几盏路灯，亮着，但照不到这么高的地方。整座学校安静得像被搬空了。

星野靠在水塔的水泥基座上，一条腿伸着，另一条屈起来，手臂搭在膝上。那只灰白的手提箱就放在她脚边，靠得很近。

她没在睡。眼睛是睁着的。

听见楼梯口的动静，她的头偏了一下，但没有立刻转过来。

「……哎呀。」

声音很轻，不像白天那种拖长的调子。

「这么晚还不睡，明天要起不来的哦。」

她终于转过头。粉色的头发被风吹得有点乱，头顶那丛呆毛往前倒着。异色的眼睛在暗处看不分明，只有很近的距离才能看出左蓝右金。

「过来坐吧。」她拍了拍身边的台阶，「这边风小一点。」

等你坐下，她把那条伸着的腿收回来，双手抱住膝盖，下巴搁上去。

沉默了一小会儿。

「大叔我啊，」她开口，语气慢慢回到平时那种懒散，「晚上经常在这儿。」

「不是失眠。」她补了一句，挺快的，「就是……坐一会儿。坐一会儿就下去走走。」

她伸手拍了拍脚边的手提箱，动作很自然，像拍一只老狗的脑袋。

「这个啊，」她说，「好用嘛。顺手。」

风又吹过来一次，她的头发被吹到脸前。她抬手把头发别到耳后，动作很慢。

「你来得正好。」她忽然说。

「我正想说，今天巡逻你来不来。」

她侧头看你，笑了一下。那个笑很浅，而且很快就收了。

「不过我先说好啊——」

她伸出一根手指，指了指你。

「不许告诉芹香。她会跳起来骂我的。」

她站起身，拍了拍裙子，然后弯腰提起手提箱。动作很轻，一点也不像提着一面能挡高温射线的盾。

「走吧。」

她往楼梯口走了两步，回头。

「哦对了。」

「你要是走不动了就说。大叔我啊，虽然看着这样——」

她停了一下，好像在斟酌要不要把这句话说完。

最后她还是说了，声音比刚才低一点。

「——其实还挺能撑的。」
