你在副线的车流里骑车，保持着一个不快不慢的速度。坡道顶上，一辆车停在路边，双撑支着，旁边蹲着一个人——是你约的人。

你按了一下刹车，车滑到那个人的位置，停稳。脚撑地，没有下车。

