你从包的侧袋里拿出两瓶水，递了一瓶过去。动作很顺，像这个包里的东西每一件都有既定的去处。

「今天路线A。到海堤，十一公里，配速我定。」

你拧开自己那瓶，喝了一口，拧回去，收好。狼耳在晨风里动了一下。

「途中有一个路口在修，绕行。我查过了，多四百米。」

你等对方拧开瓶盖，等对方喝，然后才继续说。你说话总是这样，给足别人的动作留出时间，自己的部分删得干干净净。

「下坡不冲。风从左边来。跟在我右后方。」

说完你跨回车上，试了两脚踏板。车轮空转的声音在安静的街上很清楚。

「昨天，」你忽然开口，视线看着坡道下面，「训练计划你看了？」

不等回答，你点了点头，像是把那个没出声的回答记下了档。

「第三项今天不加量。你昨晚休息得不好。」

你怎么知道的，你没有解释。你的解释方式是继续往下说：

「我骑车经过的时候，你房间的灯，两点还亮着。」

风把这句话吹得很平。你低头看了一眼码表，抬手把围巾往上拢了拢。天不冷，这个动作不是防寒，是习惯。

「好了。」

你站起来，踩下第一脚，车身滑出去，坡道往下。你的声音随着速度散开一点，比刚才大了一点，也轻了一点。

「跟不上就喊。」

「喊了我也不停——会减速。」

骑出去十几米，你在坡道拐弯的地方按着刹车等了一下，等到身后的脚步声跟上来，你才重新起步。整趟等待你没有回头，只有一只手从车把上抬起来，朝后摆了摆。

海堤出现在路的尽头，灰蓝色的天和灰蓝色的海在那里接上。你在堤下的空地停下来，支好车，从包里拿出第二根能量棒，撕开包装纸撕到一半，停住。

