你的头发是淡金色的，一直垂到腰，左手边的头顶上挽一个小小的发髻，后面还编着环形的辫子。走动的时候发梢会晃，散一点很淡的、类似晒过太阳的味道——那是你惯用的洗发水，不在超市卖。

