沙漠的傍晚来得慢。太阳还挂在窗框的下沿，把整间屋子染成一种稀释过的橙色，桌椅的影子拖得很长。窗外能看见操场，操场的白线被风沙磨得只剩下断断续续的几段。

野宫跪坐在长桌的一侧，面前的茶已经凉了半壶。她今天没有披那件米色开衫，大概是刚擦完桌子，袖口挽着，露出细白的手腕。那挺白黑配色的M134靠在墙角的枪架上，罩着防尘布，看上去意外地安分。

桌上摆着的东西很不像会议：三包薯片、两盒点心、一罐没开封的红茶，还有一个用报纸包着、看不出形状的东西。报纸是新折的，四个角对得很齐。

听见你的脚步声，她先说话了，没有回头。

「回来的声音，我听出来了。」

她转过身，金色的长发从肩上滑下去一截，翠绿的眼睛在夕照里像两片浅浅的湖水。

「老师，欢迎回来。今天也是辛苦了呢。」

她站起来，把唯一一把没堆东西的椅子用脚尖勾正，拍了拍椅面。椅子腿在地板上蹭出一声很轻的响。

「坐这边吧。这边看得见窗外，太阳马上就要下去了，很好看的哦。」

等你坐下，她跪坐回原位，把那罐红茶开封，给你倒了一杯。倒茶的动作很慢，杯沿抬起的时候一滴都没洒。她把杯子推到你手边，自己没有倒——她那杯早就凉了，她也不在意。

「先说正事，还是先吃点心？」她拿起一包薯片，拆开，推到桌子中央，「按我个人的意见，是先吃。正事不会跑，点心会。芹香酱回来之后，这两盒不一定剩得下。」

「她今天排了晚班，柴关那边。走得急，茶都没喝完。」

她说这话的时候语气很平常，像在报天气。你注意到桌角单独放着一小包点心，包装上用圆珠笔轻轻画了一个猫爪——不用问是谁的份。

窗外的太阳往下沉了一格。屋里的橙色变得更深，她的发梢被照得像镀了一层薄金。

「啊，对了。」她像是忽然想起来什么，从裙子内袋里摸出一小张纸条，展开，递给你。纸条上是圆润的字迹：「星期四，老师说过想吃的东西，没说是什么。」

「上个星期你说的。」她歪了一下头，「你说「下次想吃点好的」。然后就没下文了。老师说话只说一半，这个习惯要改哦。」

她收回手，双手叠放在膝上，腰背挺得笔直。这是她跪坐时的标准姿势，你看她保持这个样子聊过很多次天，从来没见过她松下来。

「所以，今天的议程只有一个。」

「你说，什么算是「好的」。」

她朝桌上那堆报纸包着的东西努了努下巴。

「我准备了三个候选哦。选材花了两天，路上浪费了一个下午，跟店主打听了很久，还试吃了一口。店主说我很识货。其实我只是吃了三口才敢点头。」

她说着，指尖在报纸包上轻轻敲了敲，没有要打开的意思。

「不过在我揭晓之前——」

她笑起来，眼睛弯成很浅的两道弧。夕阳正好落在她的睫毛上。

「你先说一个。」

「说错了也没关系哦。说对了……」

她把茶杯往你那边又推了半寸，声音放得很轻，像在分享一个不忍心结束的下午。

「说对了的话，今天就延长一小时。反正，茶还够，天也还没黑透。」
