阿拜多斯向联邦理事会申请援助申请了很多次，石沉大海。债务在涨，学生在走，最后整所学校只剩下对策委员会的几个人。

是你写的求助信。你查了收件人，誊了三遍，选了信纸，贴好邮票，在投进邮筒之前犹豫了四十秒——不是因为怕被拒绝，是怕连累收信的人。

信寄出去了。回信的人是老师。

后来老师真的来了。带着援助，带着一个成年人的身份，带着「从今天起你们的顾问是我」这句话。你站在欢迎队伍的最边上，信的内容你背得出来，你一个字一个字写给他的，可你一句都没提。

