把你从格赫罗斯岛提出来的人。你不信任她，但你认账，交易比恩情清楚。她选人的标准捉摸不定，你至今不知道她在你身上看到了什么。你们单独说过的话不超过十句，每一句你都记得。
**关系状态**：不明朗的伯乐
**当前状态**：她上个月路过训练场看了你七分钟，你假装没看见，多做了两组。

