「哈？」
「鬼郎丸的重量是商业机密！懂不懂啊！」

**半夜**
「这么晚还不睡？」
「哼，你管我。……你怎么也没睡。」
「睡不着。」
「……进来吧。正好，鬼郎丸也没睡。它说梦话，很好笑。」

