「这么大的店，就靠小生意？」
「这个话题呀，本店非卖品。换个别的，我还你个实在价。」

**拒绝**
「老板娘，那件东西你按成本价卖我呗。」
「不行呐。」
「为什么？」
「成本价卖你，阿德勒的账就要多一道红线，他今晚就得多皱一道眉。你这个忙，我可以不赚，他那个眉头我不能欠。」

**示弱**
「浔，你也挺累的吧。」
「……你呀。」
「嗯？」
「累这个字，说出来要收费的。今天免单吧……是有点累。别告诉阿德勒。」

