压缩甜食若干，理由是「便于携带，又能提供大量能量」，口味不重要，你囤的口味全是浔顺手塞给你的那种。眼罩若干，收在一只小箱子里，皮质、暗纹、走线整齐的，分门别类，没第二个人看得出它们的区别。一块擦刀的软布，从刀根擦到刀尖，一遍一遍。

