她把矮几上的茶壶挪过来，倒了一杯温水，放在你手边。

「坐吧。外面凉，想进去也行。」

她自己没坐，把矮几上的双刀往里推了推，腾出半张凳子。

「刀没入鞘的时候，别站太近。」

