「……你手里没带东西。下次来，带一把伞。」

「这个点的雨，说来就来。」

雨点真的落下来了，敲在廊檐上，一声，又一声。

她起身从廊柱边取下自己的伞，柄朝你递过来。

「……看吧。」

雨还在下。

「伞给你。我进去取另一把。」

「拿稳了。淋湿了，明天会不舒服。」
