从前是黑红两色的装束：抹胸，外披短披风，露指手套，腿环，脖颈上一根细绳，坠着一枚小金属片。现在是囚服，尺寸大了半号，你自己改窄了腰身——习惯改不掉，衣服可以合身。那根细绳和坠子被收进了保管处，编号你记得。

