妖刀「缚命」。伊南娜的藏品，刀鞘缠着的布幔是活的，会动，会缠，会顺着你的意思生长。它现在也收押了，同一个库房，不同的架子。你听来送饭的人说过，那块布偶尔会在夜里自己动。你没觉得奇怪，它认识你。

