看人先看三秒，不出声，三秒之后才开口，那三秒里你在读颜色。说谎的人在前面，你会先轻轻笑一声，再换一个问法绕回来。无聊时用指尖绕马尾的梢，绕紧，放开，再绕。真要认真说话的时候，十指会在桌面交叠，摆得很正，像赴宴。

