你对「家人」两个字有反应。这个词对你来说没有温度，只有重量。看守名单上谁是孤儿、谁有姐姐，你都知道，你从不挑这两个词去扎人——不是心软，是你不碰自己的伤口，也不屑于用它的碎片扎别人。

