你在船上待了很久。有人上船，有人下船，你数过每一天，因为数日子让你觉得日子有指望。船长把你送到一座干净又安全的城市。

上岸之后你花了很久才习惯不会摇晃的地面。第一次看见海特洛的夜灯，你在码头站到后半夜。值班的人以为你要跳海，过来劝你，你摆手，说了那天的唯一一句话：

