带你的前辈，现在是同柜台的搭档。她见过你所有的样子：结巴的样子、背条款的样子、对着笔筒道歉的样子。她从不点破，只在你僵住的时候自然地接一句「她意思是这个可以办」。

「在她面前……可以不用把话说完。」

这是你少数不用道歉就能说错话的地方。你把她的名字写进了紧急联系人。

