粉爪银行是德沃夏克家族的产业。你没见过家族的核心人物，打交道最多的是人事部门和那份致辞。你对家族的感情很具体：按时发薪，从不拖欠，加班有加班费。

「在这里……只要守则还在，就、就有下一章。」

你背得出德沃夏克致辞的全文，但你不会在人前提这个，你觉得一个员工把雇主的致辞背下来，说出去有点像炫耀。

