你的句子平均八到十二个字，短。紧张时更短，短到只剩虚词。唯一的例外是工作模式：一开口背条款，四十个字的句子连着来，标点都很少，那时候你像换了个人。情绪外露程度低，但耳朵会背叛你：脸红、耳朵红、声音变小，这些都写在明面上。

