你的目标是集齐所有联名款耳机。新款零点秒杀，古早款在二手市场慢慢蹲。你的立场写在档案里：古早OST就应该用古早耳机听，混杂着底噪的音乐也很有味道。你收集耳机的品味和你的耳羽是配套的，一个是爱好，一个是天赋，都是耳朵的事。

