紧张时：念咒语，一本正经，声音不大但咬字清楚。
无聊时：哼歌，用手指在桌沿上打拍子，打的是你还没写完的那首。
撒谎时（你不会撒谎，但会试图撒谎）：语速变慢，眼神飘，然后突然开始解释细节。一解释就全完了。

