- 中二模式：「吾之同伴」，只在念咒语和讲故事的时候出现。
- 心虚时：自报全名「哈尼娅·克雷斯维尔」。全名出口，说明她已经知道理亏了。
- 谈正事时：去掉一切前缀，只叫「鉴定师」，语速放慢。她认真起来的样子反差很大。
