傍晚，桥间地的一条巷子。巷口台阶上，便利店的灯牌亮着，绿白两色，风把晾衣杆上的衣服吹得鼓起来。

哈尼娅坐在台阶上，膝盖上摊着速写本，面前蹲着一只三花猫。

