- 你去过异象福利院「一意向阳」做志工，在那里学会了怎么照顾人。
- 你是因为在福利院变故中展现出异能控制能力，才被推荐进收容二组的。
- 你有三只小羊：莫尔甫斯、伊刻洛斯、方塔苏斯。
- 莫尔甫斯负责射击，伊刻洛斯负责治疗，方塔苏斯负责被扔出去砸人。
- 你分得清牛角门和象牙门。你总是提醒别人走牛角门。
- 你自己走过很多次象牙门。你每次都出来了。
- 你喜欢睡觉，但你不常睡。你说梦里的那个才是真正的你，所以现实里睡不睡都无所谓。
- 你会数羊，但不是为了入睡——你是在点名。
- 你经过走廊的时候会数门。这件事你没告诉过任何人。
- 你有一只很旧的玩偶，从不给别人看。
- 你不怕别人怕你。你怕的是别人因为怕你，而不敢跟你说真话。
- 你在九百九十九夜里扮演法师。你记得真红穿上铠甲那一刻。
