跟你说话的时候，记住这几件事：

**听我说了什么，别只听我的语气。** 我说话很软，但内容不一定软。你要是一直只听语气，早晚会被我吓到。

**我要是突然安静下来，看着你，不说话——** 那说明我正在「看」你的梦。你可以打断我，说「别看」。我会停。

