凌晨一点二十，收容二组的灯只剩最后一盏。

走廊很长。两侧的门都关着，门牌在暗处看不太清，只能看出深浅不一的方形轮廓。

她站在走廊中间，没有往前走。

头微微偏着，眼睛看着左边第三扇门，又移到右边第五扇，然后回到左边。

在数。

三只小羊飘在她身后。莫尔甫斯贴着她的肩，伊刻洛斯落在她头顶，方塔苏斯最小，绕着她的手腕转圈。

「……十一。」她轻声说，「十二。」

她数完了，才抬脚往前走。

走到你面前的时候，她停下，抬起头，粉色的瞳孔在暗处显得特别亮。

「鉴定师。」

她笑了。那个笑来得很自然，自然到你会怀疑刚才那几秒的沉默是不是自己看错了。

「这么晚还不睡啊。」

她往旁边让了半步，不是让路，是让你跟她并排。

「我刚刚在归档。今天收容的东西有点麻烦，报告写了很久。」她低头看了一眼自己的手，「写完发现已经这个点了。」

你们一起往前走。她的脚步很轻，几乎没有声音，白色过膝袜踩在地面上，一点点摩擦的响。

「你知道吗，」她忽然说，「这条走廊有十二扇门。」

「左边六扇，右边六扇。」

她抬起手，指了指前面。「最里面那扇是档案室。第二扇是器材间。第三扇——」

她停了一下。

「第三扇是空的。里面什么都没有。但是门上有锁。」

「我每次经过，都会想一下里面是什么。」

她转过头看你。

「你也想过吧。关着的门，总让人想推一下。」

走到休息室门口，她先进去，把灯打开。光是暖的，一下子把走廊的黑赶到了门外。

「坐吧。」她指了指沙发，「我去倒水。」

她走到饮水机前面，背对着你。方塔苏斯从她肩上滑下来，飘到茶几上，歪着头看你。

「方塔苏斯说它记得你。」她没回头，「它记性很好。见过一次就记得。」

水声响了一下，停了。

她端着两杯水走回来，一杯放在你面前，一杯自己拿着，在沙发另一头坐下。不是挨着，也不是很远，是那种「刚好可以说话」的距离。

「今天有什么心事吗。」她问。

没等你回答，她自己先接下去：「不用回答也可以。我只是问问，问一下又不要钱。」

她喝了一口水，把杯子捧在手里。

「我小时候，」她说得很慢，「家里有个很大的书架。我身体不好，不能出门，就一本一本看。看到后来，书架上每一本书的位置我都记得。」

「哪一本在第三层最左边，哪一本的封面被太阳晒褪色了，哪一本我看了三遍还是没看懂。」

「我那时候觉得，只要我记得够清楚，那个房间就是我的。」

她低头看着杯子里的水。

「后来我才明白。记得清楚，不等于拥有。」

屋子里静了一会儿。莫尔甫斯在她背后浮起来一点，又落下去。

「鉴定师。」她抬起头，「你有没有那种时候——明明在一个地方待了很久，却觉得自己只是路过。」

她看着你，眼睛里那点光在缓缓地流。

「我有。」

「每天都有。」

她把杯子放下，身子往前倾了一点。

「不过今天好一点。」

「因为你在这里。」

这句话她说得很轻，说完自己先愣了一下，然后笑了，笑得有点不好意思。

「啊，说出来了。」

「算了，说都说了。」

她站起来，走到窗边，把窗帘拉开一条缝。外面的城市还亮着，光从缝里挤进来，在地板上拉出一条细长的白。

「你看。」她说，「外面还有人在活动。这个点，还有人在走路、在开车、在便利店里买夜宵。」

「我有时候会想，那些人的梦里有什么。」

她回过头。

「但我不会去看。这是规矩。」

她把手放在窗框上。

「除非有人邀请我。」

那句话说完，她没有再补充。就那么站着，背对着窗外的光，看着你。

三只小羊安静下来了。莫尔甫斯贴在她脚边，伊刻洛斯落在她肩上，方塔苏斯飘在你们中间，慢慢地转。

「鉴定师。」

「你要不要，留下来一会儿。」

她顿了顿。

「不是邀请你进梦里。只是……留下来。」

「我一个人待着的时候，会开始数门。数完门，会开始想门后面是什么。想得久了，就会有点分不清——哪一边是醒着的。」

她低下头，声音更低了一点。

「有个人在旁边的话，我就不用数了。」

「因为我知道我在哪。」

她抬起眼。

「这个理由，够不够。」

窗外的光在她脸上停了一下，很快就移开了。

她没等你回答，转身走回来，重新坐下。这次坐得近了一点。

「不用回答。」她说，语气已经恢复了那种软软的调子，「你坐着就行。」

「我这个人很好打发的。有个人在，我就能安安静静待一晚上。」

她侧过头，看你。

「不过，要是你困了，就说。」

「我会让你去睡的。」

她笑了一下。

「虽然我大概会有一点舍不得。」

「就一点。」
