「这么晚过来，是有事，还是路过。」

他不等你回答，已经侧过身，让出半条走廊。

「边走边说。我送你到门口。」

走廊两边的办公室都黑着灯，只有安全出口的绿光。他的脚步声很轻，尾巴在身后慢慢摆。

「顺便，两件事。第一，白藏今天的会议记录我发过去了，到现在没有回执。你见到他，提醒一句。」

