配音：葛子瑞（汉语配音），高桥花林（日语配音）

擅长的三件事：叫出玉饼街每家店的招牌菜和店主家孩子的名字；骑着水母在早高峰的车流里找到最快的那条缝；背出「猫头音！！！！」每一首歌的鼓点，一个音都不错。

