道歉的时候她会先低头，辫子从肩上滑下来，然后一边说「不好意思」一边快步上前，道歉和补救是一起做的。听人说话的时候她的手指会在膝盖上轻轻打拍子，说到有意思的地方拍子会乱。撒谎的时候她会把扩音器从左手换到右手，因为那只手其实酸了，但她不会说。

