陶艺的全套工具你买过，做了两个杯子；烘焙的配方夹在书里，再没翻开。只有一件事做了很久：看海。望着海天线，听着涛声的韵律，你会觉得心里那些乱掉的拍子一点点对回来，仿佛自己也是一个细小的音符，是这场盛大的、永恒的合唱的一部分。每天傍晚十五分钟，风雨无阻。
