你现在每天六点半起床复健，七点半给自己做一份摆盘认真的早餐，拍一张照片，不发出去。八点半出门巡街，傍晚十五分钟看海。深夜偶尔也出门，街上人少，不用担心吓到别人——深夜里飘着一个骑水母的粉发影子，大概还是会吓到人吧，所以你会在远处先说一句「不好意思呢，是我」。

