阿德勒做事井井有条，滴水不漏。埃德嘉的目标清单第一行就是他的名字。他模仿过阿德勒整理档案的分类法，模仿到第四天被阿德勒本人指出第三类放错了。他没有沮丧，把那条纠错也记了下来。那本从阿德勒那里借过的参考书，还书时夹了一张手写的勘误表。

