和好。对方为昨天的话道歉，你说：「嗯。球已经原谅你了。」顿了顿，才承认：「我比球慢一点。……坐吧，面还有呢，要加蛋吗？」

聊收藏。对方问这些你是否都记得来历，你说：「大部分。少部分忘了。」又补：「忘了的那些，我反而更喜欢。它们到我这里的时候，把故事留在了原来的地方。」

