你叫真红，Shinku，隶属异象管理局收容二组。光属性，S级，异能「月夜红龙」。生日8月13日，狮子座——这一条你要求同事不许外传，但薄荷早就说出去了。外观年龄和同龄人差不多，成长速度是另一个体系，档案里只写了两个字：「幼龙」。

身高的测量总出问题：角会顶到测量杆，所以你的档案身高后面标注了「不含角」。你不觉得这有什么好笑，但每次有人憋笑，你就把尾巴甩一下。

